'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tiers={primary:'第一批',supplement:'第一批补充',secondary:'第二批',verify:'先核实',platform:'平台入口'};
const shortNames={'国选到家（北京国选到家公司）':'国选到家','58到家（58同城运营的当前入口）':'58到家 · 当前入口','天使来了（北京妈妈乐科技有限公司）':'天使来了','北京春宇家政服务有限公司（简介写春雨，名称需核实）':'北京春宇家政（名称待核）'};
const name=n=>shortNames[n]||n;
const canonical=n=>({'58到家':'58到家（58同城运营的当前入口）','国选到家':'国选到家（北京国选到家公司）'}[n]||n);
const tierClass=t=>['primary','supplement'].includes(t)?'blue':t==='verify'?'amber':'';
let DATA,items=[],evidence=[];
const total=()=>items.length;
const researched=()=>items.filter(r=>r.research);
const countTier=t=>items.filter(r=>r.tier===t).length;
const businessLabel=r=>({confirmed:'有北京育儿业务线索',pending:'北京育儿业务待确认',platform:'平台入口'})[r.businessStatus];
const researchLabel=r=>r.research?(r.evidenceStatus==='experience'?'有具名体验材料':'检索后独立体验不足'):'研究记录整理中';
const dialog=$('#agency-dialog');
const links=(urls,label='资料来源')=>urls.filter(u=>/^https?:\/\//.test(u)).map((u,i)=>{if(u.includes('yu-angel.com.cn'))return '<span class="source-unavailable">原官网：证书及页面状态异常，未作为当前接单入口</span>';let host;try{host=new URL(u).hostname.replace(/^www\./,'');}catch{return '';}return `<a class="source-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${i+1} · ${esc(host)} ↗</a>`;}).join('');
const openButton=(r,label='查看条款与口碑')=>`<button class="text-button" data-agency="${r.id}">${label} ↗<span class="sr-only">：${esc(r.name)}</span></button>`;
const head=(en,title,description)=>`<div class="page-heading"><div><p class="eyebrow">${en}</p><h1>${title}</h1><p class="intro">${description}</p></div></div>`;
const byName=n=>items.find(r=>r.name===n);
function renderShortlist(){renderScoredShortlist();}

function setupDirectory(){
 $('#directory').innerHTML=head('AGENCY DIRECTORY','逐家调查，逐项比较',`${items.length} 份完整调查档案，其中 ${items.filter(r=>r.businessStatus==='confirmed').length} 项有北京育儿业务线索、${items.filter(r=>r.businessStatus==='pending').length} 项业务待确认、${countTier('platform')} 个平台入口。`)+`<div class="directory-notice"><strong>按当前权重保障分排序；业务待确认与平台入口放在其后。</strong> <a href="#scores">查看完整评分标准和理由</a>。 已检索并不等于已确认所有事实；“未找到独立体验”与“没有投诉”含义不同。当前接单、库存及向你提供的合同尚未直接核验。</div><div class="filters"><label class="search-label"><span class="sr-only">搜索机构、公司或区域</span><input type="search" id="agency-search" placeholder="搜索机构、主体、区域…"></label><label><span>机构类型</span><select id="category-filter"><option value="all">全部类型</option>${[...new Set(items.map(r=>r.category))].map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label><span>北京育儿业务</span><select id="business-filter"><option value="all">全部状态</option><option value="confirmed">有业务线索</option><option value="pending">业务待确认</option><option value="platform">平台入口</option></select></label><label><span>体验证据</span><select id="coverage-filter"><option value="all">全部条目</option><option value="experience">有具名体验材料</option><option value="limited">检索后独立体验不足</option></select></label></div><div class="results-line"><p id="directory-count" role="status" aria-live="polite"></p><button class="text-button" id="reset-filters">重置筛选</button></div><div class="table-wrap"><table class="directory-table"><thead><tr><th>机构 / 平台</th><th>保障资料参考分</th><th>更换与退出</th><th>调查与口碑</th><th><span class="sr-only">查看详情</span></th></tr></thead><tbody id="directory-rows"></tbody></table></div><div id="empty-directory" class="empty" hidden>没有符合条件的条目。试试缩短关键词，或重置筛选。</div>${coverageAppendix()}<details class="method registry"><summary>北京市人社局30家品牌企业名录</summary><p>用于发现机构、核对主体；不把培训、保洁或养老企业自动当成育儿嫂机构，也不把入选名录作为服务质量排名。</p><div class="registry-grid">${DATA.registry.map(r=>`<div><strong>${esc(r['关联品牌'])}</strong><span>${esc(r['公司'])}</span></div>`).join('')}</div>${links(['https://rsj.beijing.gov.cn/bm/ztzl/ssjzlwpp/'],'官方名录')}</details>`;
 ['agency-search','category-filter','business-filter','coverage-filter'].forEach(id=>$('#'+id).addEventListener('input',renderDirectoryRows));
 $('#reset-filters').addEventListener('click',()=>{$('#agency-search').value='';['category-filter','business-filter','coverage-filter'].forEach(id=>$('#'+id).value='all');renderDirectoryRows();});renderDirectoryRows();
}
function coverageAppendix(){const c=DATA.coverage;if(!c)return '';return `<details class="method"><summary>机构范围：从哪里查漏，哪些没有计入？</summary><p>${esc(c.description)}</p><div class="coverage-sources">${c.sources.map(x=>`<p><strong>${esc(x.name)}</strong> · ${esc(x.scope)}<br><a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">查看原始名录 ↗</a></p>`).join('')}</div><p>${esc(c.limit)}</p><details><summary>逐项筛选记录 · ${c.screening.length} 条</summary><div class="screening-list">${c.screening.map(x=>`<article><strong>${esc(x.name)}</strong><span class="tag">${esc(x.status)}</span><p>${esc(x.reason)}</p>${x.url?`<a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">原始线索 ↗</a>`:''} ${x.agencyId?`<button class="text-button" data-agency="${esc(x.agencyId)}">完整调查 ↗</button>`:''}</article>`).join('')}</div></details></details>`;}
function renderDirectoryRows(){
 const q=$('#agency-search').value.trim().toLowerCase(),c=$('#category-filter').value,v=$('#coverage-filter').value,bs=$('#business-filter').value;
 const list=items.filter(r=>(!q||[r.name,r.entity,r.address,r.contact].join(' ').toLowerCase().includes(q))&&(c==='all'||r.category===c)&&(v==='all'||r.evidenceStatus===v)&&(bs==='all'||r.businessStatus===bs)).sort((a,b)=>({confirmed:0,pending:1,platform:2}[a.businessStatus]-{confirmed:0,pending:1,platform:2}[b.businessStatus])||scoreValue(b).total-scoreValue(a).total||a.id.localeCompare(b.id));
 $('#directory-count').textContent=`显示 ${list.length} / ${total()} 个条目`;$('#empty-directory').hidden=!!list.length;
 $('#directory-rows').innerHTML=list.map(r=>`<tr><td data-label="机构 / 平台"><button class="name-button" data-agency="${r.id}">${esc(name(r.name))}</button><span class="table-sub">${esc(r.category)}</span><span class="table-sub ${r.businessStatus==='pending'?'pending-status':''}">${businessLabel(r)}</span></td><td data-label="保障资料参考分">${scoreBadge(r)}</td><td data-label="更换与退出"><p class="cell-excerpt">${esc(r.replacement)}</p>${r.research?`<details class="cell-refund"><summary>退费 / 退出</summary><p>${esc(r.research.findings.refund)}</p></details>`:''}</td><td data-label="调查与口碑"><span class="coverage-yes">${r.research?`${r.research.queries.length} 组检索 · ${r.research.sources.length} 条来源`:'研究记录整理中'}</span><span class="table-sub evidence-status">${researchLabel(r)}</span>${r.complaintAudit?'<span class="table-sub">含投诉平台与官方公示补查</span>':''}${r.xhsAudit?'<span class="table-sub">含小红书站内核查</span>':r.notes.length?'<span class="table-sub">有已读小红书材料</span>':''}</td><td>${openButton(r,'调查档案')}</td></tr>`).join('');
}
function caseCard(e){return `<details class="evidence-card"><summary><div><div class="evidence-tags"><span class="tag ${e.platform==='小红书'?'pink':''}">${e.id?.startsWith('C-')?esc(e.platform):`${esc(e.id)} · ${esc(e.platform)}`}</span><span class="evidence-city">${esc(e.city)}</span><span class="tag">${esc(e.type)}</span>${e.relevance?`<span class="tag">${esc(relevanceLabel(e))}</span>`:''}</div><h3>${esc(name(e.brand))}<span> · ${esc(e.job)}</span></h3><p>${esc(e.summary)}</p><span class="case-date">${esc(e.date)}</span></div><span class="expand-symbol" aria-hidden="true">＋</span></summary><div class="evidence-detail"><dl><dt>材料性质</dt><dd>${esc(e.type)}</dd><dt>相关范围</dt><dd>${esc(relevanceLabel(e))}</dd>${e.title?`<dt>材料标题</dt><dd>${esc(e.title)}</dd>`:''}${e.department?`<dt>处理部门</dt><dd>${esc(e.department)}</dd>`:''}${e.readStatus?`<dt>读取情况</dt><dd>${esc(e.readStatus)}</dd>`:''}${e.query?`<dt>官方查询方式</dt><dd>名称：${esc(e.query)}；公示时间：${esc(e.published||e.date)}。来源链接进入平台后按名称查询。</dd>`:''}<dt>处理结果</dt><dd>${esc(e.resolution)}</dd>${e.response?`<dt>企业回应</dt><dd>${esc(e.response)}</dd>`:''}<dt>使用边界</dt><dd>${esc(e.limits)}</dd></dl><a class="source-link" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">打开原始材料 ↗</a></div></details>`;}
function setupReviews(){
 evidence=[...DATA.notes.map(n=>({id:n.id,brand:canonical(n.brand),platform:'小红书',date:n.date,city:n.city,job:n.service,type:n.sentiment,summary:n.summary,resolution:n.resolution,limits:n.limits,url:n.url})),...items.flatMap(publicCases)];
 const xCount=evidence.filter(e=>e.platform==='小红书').length,other=evidence.length-xCount;
 $('#reviews').innerHTML=head('REPUTATION & EVIDENCE','每条经历，都保留出处与后续','机构自述、客户经历、异地参考和排除材料分别标明。每家的完整调查档案，也记录没有找到的证据。')+`<div class="review-metrics"><div><strong>${researched().length}</strong><span>条目有逐家调查记录</span></div><div><strong>${xCount}</strong><span>小红书已读材料</span></div><div><strong>${other}</strong><span>其他公开材料</span></div></div><div class="evidence-note"><strong>${evidence.length} 条材料不等于 ${evidence.length} 个已核实的北京育儿嫂案例。</strong><p>包含历史、异地、异工种、商家自述和排除材料。单方描述未独立核验；“完成投诉”“已结案”不等于实际退款。没有订单量作分母，不计算投诉率或满意度。</p></div><div class="section-heading"><h2>先选机构，再看具体经历</h2><span>筛选不会隐藏原文的使用边界</span></div><div class="filters evidence-filters"><label><span>材料来源</span><select id="source-filter"><option value="all">全部材料 · ${evidence.length}</option><option value="小红书">小红书 · ${xCount}</option><option value="other">其他公开材料 · ${other}</option>${[...new Set(evidence.filter(e=>e.platform!=='小红书').map(e=>e.platform))].sort().map(p=>`<option value="${esc(p)}">${esc(p)} · ${evidence.filter(e=>e.platform===p).length}</option>`).join('')}</select></label><label><span>机构 / 品牌</span><select id="brand-filter"><option value="all">全部机构</option>${[...new Set(evidence.map(e=>e.brand))].map(n=>`<option value="${esc(n)}">${esc(name(n))}</option>`).join('')}</select></label></div><p class="results-line" id="evidence-count" role="status" aria-live="polite"></p><div id="evidence-list"></div><details class="method"><summary>全部机构的口碑结论 · ${items.length} 条</summary><div class="reputation-grid">${items.map(r=>`<article><h3>${esc(name(r.name))}</h3><span class="tag">${researchLabel(r)}</span><p>${esc(reputationSummary(r))}</p>${openButton(r,'看完整调查档案')}</article>`).join('')}</div></details><details class="method"><summary>检索方法与证据边界</summary><p>每个主表条目执行主体与北京业务、换人与退费、具名口碑与争议的定向检索，并回读相关原始网页。逐家关键词、渠道、结果及读取状态在档案里展示。</p><p>小红书站内实际打开的正文、只筛过的结果和商家发布的案例分开记录；没有站内核查记录的机构，不标成已查小红书正文。搜索覆盖并非随机抽样；没有逐一核验真实订单，也没有电话核实当前排班。</p><p>页面只显示月日的帖子保留原显示，不补造年份。没有搜到公开纠纷，不能等同于没有纠纷。</p></details>`;
 $('#source-filter').addEventListener('input',renderEvidence);$('#brand-filter').addEventListener('input',renderEvidence);renderEvidence();
}
function renderEvidence(){const s=$('#source-filter').value,b=$('#brand-filter').value;const list=evidence.filter(e=>(s==='all'||(s==='other'?e.platform!=='小红书':e.platform===s))&&(b==='all'||b===e.brand));$('#evidence-count').textContent=`显示 ${list.length} 条材料`;$('#evidence-list').innerHTML=list.length?list.map(caseCard).join(''):'<div class="empty">当前来源下没有该机构的材料。可将来源切换为“全部材料”。</div>';}
function setupContract(){
 const cards=[['谁负责换人','合同、收款、派工和售后是否由同一主体承担？平台上的哪家公司负责提供替补？','查看：公司完整名称、盖章主体、收款方及售后联系人。'],['免费，具体指什么','免费更换次数、是否重收匹配费、不同等级阿姨的工资与服务费差价分别怎么算？','查看：次数、条件、收费项目和适用服务期。'],['多久能接上','提出换人后多久给候选、多久安排面试、多久到岗？临时离岗有没有过渡方案？','查看：候选时限与到岗时限分开写，不能只写“尽快协调”。'],['试用不合适怎么算','试用前是否签约？试用工资、中介费及第一次匹配费如何结算？试用后再换是否另收费？','查看：试用天数、费用归属及终止方式。'],['一直不合适，如何退出','连续更换仍不匹配，或约定期限内无人到岗，能否解除合同？退款按什么公式计算？','查看：扣除项目、服务中断的计时方式、退款期限与实际到账安排。'],['每次换人如何确认','原合同是否继续有效？换人单、续签或退款协议会不会改变剩余期限与原有承诺？','查看：每份补充文件的合同编号、有效期及变更条款。']];
 $('#contract').innerHTML=head('BEFORE YOU SIGN','先把“能换”问成具体条款','围绕你最在意的替换能力，向每家机构问同样的问题，答案才有可比性。')+`<div class="contract-highlight"><span>核心判断</span><p>能提供替补人选 <b>+</b> 到岗有期限 <b>+</b> 匹配失败可按约退出</p><small>只有“免费换”三个字，还不足以判断服务是否适合你。</small></div><div class="contract-grid">${cards.map((c,i)=>`<article><span class="contract-number">0${i+1}</span><h2>${c[0]}</h2><p>${c[1]}</p><div>${c[2]}</div></article>`).join('')}</div><div class="section-heading"><h2>可以直接发给机构的询问内容</h2></div><blockquote class="inquiry">您好，我在北京找育儿嫂，比较看重不合适后的换人和补位服务。请提供当前北京育儿嫂合同、完整费用表和近期可面试人选，并书面说明：<br><br>1. 本单签约、收款及负责换人的公司名称；<br>2. 免费更换条件、次数及可能产生的差价；<br>3. 换人后多久给候选、多久到岗；<br>4. 试用不合适时，工资、中介费和匹配费如何结算；<br>5. 连续更换不合适或长期无人可换时，解除与退费的公式和时限；<br>6. 临时离岗时的补位安排。<br><br>请标明上述承诺对应合同的哪一条。具体服务要求、宝宝月龄、区域与预算，我会再补充。</blockquote><details class="method" open><summary>怎样使用这份手册</summary><p>先从评分页比较换人、退出和人员筛选得分，再结合口碑提示选择几家，按相同需求索取合同与候选资料。分数低可能因为公开资料缺失，可以用机构补充的书面材料重新判断。业务待确认和平台入口先核实谁实际签约、派工和负责换人。</p><p>本页提供比较问题，未核验任何一家向你出具的具体合同。费用和服务时效需要落实在本次签约文件里。</p></details>`;
}
function researchSections(r){const d=r.research;if(!d)return '';const fields=[['entity','签约主体线索'],['beijingBusiness','北京育儿业务'],['currentOperation','当前经营线索'],['replacement','换人条件与时限'],['refund','解除与退费'],['pricing','工资与机构收费'],['vettingAndTraining','人员筛选与培训'],['supervision','督导与后续服务'],['contact','联系入口']];return `<section class="detail-section"><h3>逐项调查结果</h3><dl>${fields.map(([k,t])=>`<dt>${t}</dt><dd>${esc(d.findings[k]||'本轮未取得可确认的公开资料。')}</dd>`).join('')}</dl></section><section class="detail-section"><h3>这家的关键缺口</h3><ul class="gap-list">${d.unresolved.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="micro">以上是本次公开资料调查的结果；当前可上户人选、实际换人库存与本次合同，需要直接向机构核实。</p></section><section class="detail-section"><h3>逐条来源 · ${d.sources.length}</h3><div class="research-sources">${d.sources.map((x,i)=>`<article><div class="evidence-tags"><span class="tag">${esc(x.type||'公开资料')}</span><span class="micro">${esc(x.date||'页面未标日期')} · ${esc(x.readStatus||'见资料说明')}</span></div><a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(x.title||'查看原始来源')} ↗</a><p><strong>支持什么：</strong>${esc(Array.isArray(x.supports)?x.supports.join('；'):x.supports)}</p><p class="scope-text"><strong>使用边界：</strong>${esc(x.limitations||'属于公开材料，未独立核验实际履约。')}</p></article>`).join('')}</div></section><details class="method"><summary>实际检索记录 · ${d.queries.length} 组</summary><div class="query-log">${d.queries.map(x=>`<article><strong>${esc(x.query)}</strong><span>${esc(x.channel)}</span><p>${esc(x.resultSummary)}</p></article>`).join('')}</div></details>${r.xhsAudit?`<details class="method"><summary>小红书站内检索记录</summary><div class="query-log">${r.xhsAudit.queries.map(q=>typeof q==='string'?`<p>${esc(q)}</p>`:`<article><strong>${esc(q.query)}</strong><span>${esc(q.channel||'小红书站内')}</span><p>${esc(q.resultSummary||'')}</p></article>`).join('')}</div><p>${esc(r.xhsAudit.result||'已读取具名材料，见口碑与履约线索。')}</p></details>`:''}`;}
function openAgency(id){const r=items.find(r=>r.id===id);if(!r)return;const ev=[...r.notes.map(c=>evidence.find(e=>e.id===c.id)).filter(Boolean),...publicCases(r)];
 $('#dialog-content').innerHTML=`<div class="dialog-bar"><span>调查档案 · ${esc(DATA.checkedAt||'2026-09-21')}</span><button class="close-button" data-close aria-label="关闭机构详情">关闭 ×</button></div><div class="dialog-body"><div class="evidence-tags"><span class="tag">${esc(r.category)}</span><span class="tag">${businessLabel(r)}</span><span class="tag blue">${r.research?`${r.research.queries.length} 组检索 / ${r.research.sources.length} 条来源`:'研究记录整理中'}</span></div><h2 id="dialog-title">${esc(name(r.name))}</h2><p class="entity">${esc(r.entity||'主体资料见下方调查结果')}</p><p class="priority-reason">${esc(r.research?.conclusion||r.reason)}</p>${scoreBreakdown(r)}<div class="question-box"><strong>联系这家，优先问</strong><p>${esc(r.question)}</p></div><section class="detail-section"><h3>口碑与履约线索</h3><p>${esc(reputationSummary(r))}</p>${ev.length?ev.map(caseCard).join(''):'<div class="empty">已做具名口碑检索；本轮未取得可展示的独立履约经历。检索范围与证据缺口见下方，不能据此判断好坏。</div>'}${r.exclusions.length?`<details class="method"><summary>未作为该机构口碑采用的材料</summary>${r.exclusions.map(e=>`<p>${esc(e.reason||'')}${e.url?` <a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">原文 ↗</a>`:''}</p>`).join('')}</details>`:''}</section>${complaintAuditSection(r)}<details class="method"><summary>本次投诉补查前的调查摘要</summary><p>${esc(r.reputation)}</p><p>后续状态以本轮补查材料为准；不同订单与不同平台帖子不自动视为同一事件。</p></details>${researchSections(r)}<details class="method"><summary>早期业务线索与联系信息</summary><p>${esc(r.contact||'请从上方原始业务资料联系机构。')}</p><p>${esc(r.address||'')}</p><div class="source-list">${links(r.sources,'业务资料')}</div></details></div>`;
 dialog.showModal();dialog.scrollTop=0;document.body.classList.add('dialog-open');}
function updateCounts(){const a=items.filter(r=>r.businessStatus==='confirmed').length,pending=items.filter(r=>r.businessStatus==='pending').length;$('#nav-count').textContent=total();$('#scope-counts').innerHTML=`<div><b>${researched().length}</b><span>逐家调查档案</span></div><div><b>${a}</b><span>有北京育儿业务线索</span></div><div><b>${pending}</b><span>业务待确认，已深查</span></div><div class="scope-caption">另含 ${countTier('platform')} 个平台入口。<br>每家可查看9项发现、检索和来源。</div>`;}
function route(){const requested=location.hash.slice(1);if(requested==='main')return;const view=['shortlist','scores','directory','reviews','complaints','contract'].includes(requested)?requested:'shortlist';document.querySelectorAll('.view').forEach(el=>{el.hidden=el.id!==view;el.classList.toggle('active',el.id===view);});document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-agency]');if(b)openAgency(b.dataset.agency);if(e.target.closest('[data-close]'))dialog.close();});
dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',route);
fetch('data.json?v=complaints-v3').then(r=>{if(!r.ok)throw new Error('Data unavailable');return r.json();}).then(data=>{DATA=data;items=data.items;updateCounts();renderShortlist();setupDirectory();setupReviews();setupComplaints();setupContract();setupScores();route();}).catch(()=>{const p=document.createElement('p');p.className='evidence-note';p.innerHTML='详细资料暂时未能加载，请刷新重试，也可以先<a href="research.csv" download>下载完整清单</a>。';$('#main').prepend(p);});
